App.register({group:'platform',label:'10 / 平台与审计',routes:[{path:'platform/audit',title:'审计事件',icon:'≋',permission:'audit',render(){return UI.page('GOVERNANCE / AUDIT TRAIL','审计事件记录','记录身份变更、跨租户访问、项目操作、生产异常、导出和交付行为。',UI.btn('导出审计摘要','audit:export','btn'),`<div class="grid grid-3">${UI.metric('本月审计事件','1,284','包含系统与人工操作','≋')}${UI.metric('跨租户授权','12','当前有效授权关系','⌘')}${UI.metric('高风险操作','0','待调查事件','✓')}</div><div class="card section-gap"><div class="toolbar"><b class="small">最近事件</b><input class="search" data-filter placeholder="搜索操作人 / 事件 / 对象"></div>${UI.table(['时间','操作主体','操作行为','目标对象','结果'],DB.audits.map(a=>`<tr data-search="${a.actor} ${a.action} ${a.target}"><td class="mono">${a.time}</td><td>${a.actor}</td><td>${a.action}</td><td>${a.target}</td><td>${UI.tag(a.result,a.result==='成功'?'green':'orange')}</td></tr>`))}</div>`); }},{path:'platform/models',title:'模型能力治理',icon:'✳',permission:'platform',render(){return UI.page('PLATFORM / MODEL GOVERNANCE','模型与生产能力','企业统一接入模型能力，按租户配额、能力白名单和预算策略分配。','',`<div class="grid grid-3">${UI.metric('已接入能力','08','文本 / 图像 / 视频 / 音频','✳')}${UI.metric('可用模型','12','含备用模型','✓')}${UI.metric('今日调用','3,482','按租户记录成本','↗')}</div><div class="card section-gap">${UI.table(['能力类型','主模型','备用策略','状态','治理规则'],[['文本 / 剧本','Text Studio Pro','Text Studio Lite',UI.tag('可用','green'),'租户白名单'],['图像 / 视觉','Vision Render X','Vision Render S',UI.tag('可用','green'),'人物一致性优先'],['视频生成','Motion Forge 2','Motion Forge 1',UI.tag('繁忙','orange'),'并发配额控制'],['语音合成','Voice Studio','Voice Studio Backup',UI.tag('可用','green'),'音色授权校验'],['音频后期','Audio Master','Audio Lite',UI.tag('可用','green'),'成本阈值控制']].map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`))}</div><div class="notice section-gap">模型名称和调用量为原型演示数据，不代表已接入真实模型服务。平台运维配置不自动授予业务内容读取权。</div>`); }},{path:'platform/system',title:'系统运行配置',icon:'⚙',permission:'platform',render(){return UI.page('PLATFORM / OPERATIONS','系统运行与安全','运维管理基础设施、运行状态、备份恢复与安全配置。', '',`<div class="grid grid-3">${UI.metric('系统健康度','99.98%','演示监控指标','✓')}${UI.metric('任务队列','08','运行中 / 等待中','⌁')}${UI.metric('最近备份','02:00','每日增量备份策略','▣')}</div><div class="grid grid-2 section-gap"><div class="card"><div class="card-title">运行组件</div><div class="kpi-line"><span>API 网关</span>${UI.tag('运行正常','green')}</div><div class="kpi-line"><span>任务调度器</span>${UI.tag('运行正常','green')}</div><div class="kpi-line"><span>对象存储</span>${UI.tag('运行正常','green')}</div><div class="kpi-line"><span>模型路由</span>${UI.tag('部分繁忙','orange')}</div></div><div class="card"><div class="card-title">运维访问原则</div><p class="small muted" style="line-height:1.8">平台运维人员默认只拥有基础设施权限。必要业务内容访问需走临时授权、明确目的和审计留痕。备份、恢复和系统配置操作均需记录操作者。</p></div></div>`);}}]});
